<style>
/* ============================================================
   NIGHT RUNNER // 2077
   High-Tech Dark Minimalist (Vercel / Linear) design system
   ============================================================ */
:root{
  --bg:#08080b;
  --panel:rgba(15,15,20,.74);
  --line:rgba(255,255,255,.08);
  --line-strong:rgba(255,255,255,.16);
  --text:#f4f5f9;
  --muted:#9c9daa;
  --faint:#5f606c;
  --cyan:#22d3ee;
  --magenta:#e14eff;
  --amber:#ffb454;
  --red:#ff4d5e;
  --green:#5df0a6;
  --mono:ui-monospace,"SF Mono",SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  --sans:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden;background:var(--bg);color:var(--text);font-family:var(--sans);
  -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
#app{position:fixed;inset:0;background:
  radial-gradient(120% 90% at 50% 0%, #101018 0%, #08080b 55%, #050507 100%)}
canvas#view{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;
  cursor:crosshair}

/* ---------- fixed vignette + scanline overlay (pure CSS, zero cost) ---------- */
#grain{position:absolute;inset:0;pointer-events:none;z-index:15;opacity:.5;
  background:
    radial-gradient(140% 105% at 50% 50%, transparent 58%, rgba(0,0,0,.42) 100%),
    repeating-linear-gradient(0deg, rgba(255,255,255,.014) 0 1px, transparent 1px 3px);
  mix-blend-mode:overlay}
#hurt{position:absolute;inset:0;pointer-events:none;z-index:16;opacity:0;
  background:radial-gradient(120% 95% at 50% 55%, transparent 45%, rgba(255,40,60,.5) 100%)}
#flash{position:absolute;inset:0;pointer-events:none;z-index:17;opacity:0;background:
  radial-gradient(100% 90% at 50% 50%, rgba(255,60,80,.55), rgba(120,10,30,.25) 70%, transparent)}

/* ================= HUD ================= */
#hud{position:absolute;inset:0;z-index:20;pointer-events:none;opacity:0;transition:opacity .35s;
  font-family:var(--mono)}
body[data-state="playing"] #hud, body[data-state="paused"] #hud{opacity:1}
.hud-top{position:absolute;top:0;left:0;right:0;display:flex;justify-content:space-between;
  align-items:flex-start;padding:16px 20px;gap:12px}
.hud-block{display:flex;flex-direction:column;gap:3px;min-width:0}
.hud-block.mid{align-items:center;text-align:center;flex:1}
.hud-block.right{align-items:flex-end;text-align:right}
.lbl{font-size:9.5px;font-weight:600;letter-spacing:.22em;color:var(--faint);text-transform:uppercase}
.lbl span{color:var(--muted)}
.big{font-size:27px;font-weight:700;letter-spacing:.06em;line-height:1;
  text-shadow:0 0 18px rgba(34,211,238,.25)}
.sect{font-size:11px;font-weight:600;letter-spacing:.24em;color:var(--muted)}
.muted{font-size:10px;letter-spacing:.18em;color:var(--faint)}
.speed{font-size:15px;font-weight:700;letter-spacing:.08em}
.speed span{font-size:9px;color:var(--faint);letter-spacing:.2em;margin-left:4px}
.combo{margin-top:4px;font-size:11px;font-weight:700;letter-spacing:.18em;color:#0a0a0c;
  background:linear-gradient(90deg,var(--cyan),#7de3ff);padding:3px 9px;border-radius:4px;
  box-shadow:0 0 18px rgba(34,211,238,.45)}
.hidden{display:none!important}
.hud-bot{position:absolute;left:0;right:0;bottom:0;display:flex;justify-content:flex-start;
  padding:0 20px 16px}
.meters{display:flex;flex-direction:column;gap:7px;background:var(--panel);border:1px solid var(--line);
  border-radius:10px;padding:11px 14px;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.meter{display:flex;align-items:center;gap:10px}
.ml{font-size:9px;font-weight:700;letter-spacing:.22em;color:var(--faint);width:44px}
.track{width:min(170px,32vw);height:4px;border-radius:2px;background:rgba(255,255,255,.07);overflow:hidden}
.fill{height:100%;width:100%;border-radius:2px;transform-origin:left center;transform:scaleX(1);will-change:transform}
.fill.hp{background:linear-gradient(90deg,var(--green),#b8ffd9)}
.fill.hp.low{background:linear-gradient(90deg,var(--red),#ff9aa4)}
.fill.heat{background:linear-gradient(90deg,var(--cyan),var(--amber) 70%,var(--red))}
.fill.cell{background:linear-gradient(90deg,#8b93ff,var(--cyan))}
.mv{font-size:9.5px;letter-spacing:.1em;color:var(--muted);width:34px}

/* ---------- announcements ---------- */
#announce{position:absolute;top:16%;left:0;right:0;text-align:center;pointer-events:none;z-index:21;
  opacity:0;transform:translateY(-8px);transition:opacity .3s,transform .3s}
#announce.show{opacity:1;transform:none}
#announce .big{font:700 22px var(--mono);letter-spacing:.42em;padding-left:.42em;
  text-shadow:0 0 24px rgba(255,255,255,.25)}
#announce .small{font:600 10.5px var(--mono);letter-spacing:.3em;padding-left:.3em;
  color:var(--muted);margin-top:7px;text-transform:uppercase}

/* ================= SCREENS ================= */
.screen{position:absolute;inset:0;z-index:30;display:flex;align-items:center;justify-content:center;
  padding:20px;background:radial-gradient(1200px 640px at 50% 18%, rgba(22,22,34,.28), rgba(5,5,8,.8));
  backdrop-filter:blur(11px) saturate(1.12);-webkit-backdrop-filter:blur(11px) saturate(1.12)}
.screen.hidden{display:none}
.panel{width:min(560px,100%);background:var(--panel);border:1px solid var(--line);border-radius:14px;
  padding:32px 36px 26px;box-shadow:0 30px 90px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,255,255,.05);
  max-height:calc(100vh - 40px);overflow:auto}
.panel.slim{width:min(400px,100%);text-align:center}
.kicker{font:700 10.5px var(--mono);letter-spacing:.26em;color:var(--cyan);text-transform:uppercase}
.kicker.red{color:var(--red)}
h1{font-size:clamp(30px,6.4vw,46px);font-weight:750;letter-spacing:-.025em;margin:10px 0 8px;line-height:1.02}
h1 .accent{background:linear-gradient(92deg,var(--cyan) 10%,var(--magenta) 90%);
  -webkit-background-clip:text;background-clip:text;color:transparent}
.sub{color:var(--muted);font-size:13.5px;line-height:1.65;max-width:46ch}
.controls{display:grid;grid-template-columns:1fr 1fr;gap:2px 22px;margin:22px 0 24px;font-size:12px;
  color:var(--muted)}
.controls .row{display:flex;justify-content:space-between;align-items:center;gap:10px;
  border-bottom:1px dashed rgba(255,255,255,.07);padding:7px 1px}
kbd{font:700 10px var(--mono);color:var(--text);background:rgba(255,255,255,.06);
  border:1px solid var(--line);border-bottom-width:2px;border-radius:5px;padding:2.5px 7px;margin-left:4px}
.actions{display:flex;gap:10px;flex-wrap:wrap}
.btn{appearance:none;border:0;cursor:pointer;font:650 13px var(--sans);letter-spacing:.02em;
  padding:11px 22px;border-radius:9px;transition:transform .12s, box-shadow .12s, background .12s, opacity .12s;
  color:var(--text);background:transparent;pointer-events:auto}
.btn:active{transform:translateY(1px)}
.btn:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}
.btn.primary{background:#fff;color:#0a0a0c;border:1px solid #fff}
.btn.primary:hover{box-shadow:0 0 0 1px rgba(255,255,255,.2), 0 8px 30px rgba(255,255,255,.14)}
.btn.ghost{border:1px solid var(--line-strong)}
.btn.ghost:hover{background:rgba(255,255,255,.05)}
.foot{display:flex;justify-content:space-between;gap:10px;margin-top:22px;padding-top:16px;
  border-top:1px solid var(--line);font:600 9.5px var(--mono);letter-spacing:.18em;color:var(--faint);
  text-transform:uppercase;flex-wrap:wrap}
.record{display:inline-block;font:700 10.5px var(--mono);letter-spacing:.24em;color:#0a0a0c;
  background:linear-gradient(90deg,var(--amber),#ffd9a1);padding:5px 12px;border-radius:5px;margin:2px 0 14px;
  box-shadow:0 0 24px rgba(255,180,84,.4);text-transform:uppercase}
.stats{margin:18px 0 24px}
.srow{display:flex;justify-content:space-between;align-items:baseline;padding:9px 2px;
  border-bottom:1px dashed rgba(255,255,255,.08);font-size:12.5px;color:var(--muted);letter-spacing:.04em}
.srow b{font:700 15px var(--mono);letter-spacing:.06em;color:var(--text)}
.srow.total{border-bottom:0;padding-top:12px}
.srow.total b{font-size:22px;color:var(--cyan);text-shadow:0 0 18px rgba(34,211,238,.4)}

/* ================= TOUCH UI ================= */
#touch{position:absolute;inset:0;z-index:40;pointer-events:none;display:none}
body.touch #touch{display:block}
.tbtn{position:absolute;pointer-events:auto;user-select:none;-webkit-user-select:none;touch-action:none;
  display:flex;align-items:center;justify-content:center;font:700 17px var(--mono);letter-spacing:.1em;
  color:var(--text);background:rgba(18,18,24,.44);border:1px solid var(--line-strong);border-radius:18px;
  backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px);
  box-shadow:0 10px 24px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.06)}
.tbtn:active{background:rgba(60,60,80,.5)}
.tbtn.tl{left:16px;bottom:calc(20px + env(safe-area-inset-bottom));width:66px;height:66px}
.tbtn.tr{left:94px;bottom:calc(20px + env(safe-area-inset-bottom));width:66px;height:66px}
.tbtn.jump{right:94px;bottom:calc(20px + env(safe-area-inset-bottom));width:66px;height:66px;font-size:13px}
.tbtn.fire{right:16px;bottom:calc(20px + env(safe-area-inset-bottom));width:84px;height:84px;border-radius:24px;
  border-color:rgba(34,211,238,.5);color:#bdf3ff;font-size:14px;
  box-shadow:0 10px 26px rgba(0,0,0,.4), 0 0 24px rgba(34,211,238,.18), inset 0 1px 0 rgba(255,255,255,.08)}

/* ---------- toast ---------- */
#toast{position:absolute;left:50%;bottom:22px;transform:translate(-50%,14px);z-index:60;opacity:0;
  transition:opacity .25s, transform .25s;background:rgba(20,20,26,.92);border:1px solid var(--line-strong);
  border-radius:9px;padding:10px 16px;font:600 11px var(--mono);letter-spacing:.08em;color:var(--muted);
  pointer-events:none;max-width:80vw;text-align:center}
#toast.show{opacity:1;transform:translate(-50%,0)}

/* ---------- responsive ---------- */
@media (max-width:640px){
  .big{font-size:19px}
  .sect{font-size:9.5px}
  .panel{padding:24px 22px 20px}
  .controls{grid-template-columns:1fr;gap:0}
  .hud-top{padding:12px 14px}
  .meters{padding:9px 11px}
  .hud-bot{padding:0 14px 12px}
  #announce .big{font-size:16px}
}
@media (max-height:480px){
  .panel{padding:18px 22px}
  .sub{display:none}
  h1{font-size:26px;margin:6px 0 4px}
  .controls{margin:12px 0 14px}
}
</style>
</head>
