      const f = o.f[2], p = f.p;
      if (projPt(x1, 0, a, p, 0) && projPt(x1, 0, c, p, 2) && projPt(x1, o.h, c, p, 4) && projPt(x1, o.h, a, p, 6)) {
        const fog = fogAt((a + c) / 2 - camZ);
        f.color = rgba(...o.colSide(fog));
        f.z = (a + c) / 2 - camZ; f._qs = []; o._face2 = true;
