/* ================================================================
   10. SKY / GROUND  (pre-rendered offscreen, rebuilt on resize/theme)
   ================================================================ */
let skyStatic = null, skyFar = null, skyNear = null, groundGrad = null, roadGrad = null;
function buildSky() {
  const Hh = Math.max(2, H2 + 2);
  const T = theme();
  const mk = (w, h) => { const c = document.createElement("canvas"); c.width = w; c.height = h; return c; };
  /* static layer: gradient + stars + planet */
  skyStatic = mk(Math.ceil(W) + 2, Hh);
  {
    const g = skyStatic.getContext("2d");
    const grd = g.createLinearGradient(0, 0, 0, Hh);
    grd.addColorStop(0, "#030308");
    grd.addColorStop(0.55, "rgb(" + (T.fog[0] * 0.4 | 0) + "," + (T.fog[1] * 0.4 | 0) + "," + (T.fog[2] * 0.55 | 0) + ")");
    grd.addColorStop(1, T.horizon);
    g.fillStyle = grd; g.fillRect(0, 0, skyStatic.width, Hh);
    const rng = mulberry32(0xC0FFEE);
    for (let i = 0; i < 240; i++) {
      const x = rng() * skyStatic.width, y = rng() * Hh * 0.72;
      const a = 0.15 + rng() * 0.75, sz = rng() < 0.12 ? 2 : 1;
      g.fillStyle = "rgba(255,255,255," + a.toFixed(2) + ")";
      g.fillRect(x, y, sz, sz);
    }
    const cxp = skyStatic.width * 0.74, cyp = Hh * 0.44, rp = Hh * 0.34;
    const pg = g.createRadialGradient(cxp - rp * 0.4, cyp - rp * 0.4, rp * 0.1, cxp, cyp, rp);
    pg.addColorStop(0, "#332358"); pg.addColorStop(0.6, "#191233"); pg.addColorStop(1, "#0b0817");
    g.fillStyle = pg; g.beginPath(); g.arc(cxp, cyp, rp, 0, TAU); g.fill();
    g.save();
    g.translate(cxp, cyp); g.rotate(-0.35); g.scale(1, 0.32);
    g.strokeStyle = "rgba(225,78,255,0.30)"; g.lineWidth = 2.2;
    g.beginPath(); g.arc(0, 0, rp * 1.35, 0, TAU); g.stroke();
    g.restore();
  }
  /* skyline layers with parallax */
  const LW = Math.ceil(W) + 320;
  const buildLayer = (col, hMin, hMax, wMin, wMax, winP, baseY, rngSeed) => {
    const c = mk(LW, Hh);
    const g = c.getContext("2d");
    const rng = mulberry32(rngSeed);
    g.fillStyle = col;
    let x = 0;
    while (x < LW) {
      const bw = wMin + rng() * (wMax - wMin);
      const bh = Hh * (hMin + rng() * (hMax - hMin));
      g.fillRect(x, baseY - bh, bw, bh);
      if (rng() < 0.3) { g.fillRect(x + bw * 0.45, baseY - bh - 6, 1.5, 6); }
      if (winP > 0 && rng() < 0.85) {
        const cols = Math.max(2, (bw / 7) | 0), rows = Math.max(2, (bh / 9) | 0);
        for (let r0 = 0; r0 < rows; r0++) for (let c0 = 0; c0 < cols; c0++) {
          if (rng() < winP) {
            g.fillStyle = ["rgba(34,211,238,.4)", "rgba(225,78,255,.38)", "rgba(255,180,84,.35)", "rgba(138,216,255,.35)"][((r0 * 31 + c0 * 17) & 3)];
            g.fillRect(x + 2 + c0 * 7, baseY - bh + 3 + r0 * 9, 2, 3);
          }
        }
        g.fillStyle = col;
      }
      x += bw + 2 + rng() * 14;
    }
    return c;
  };
  skyFar = buildLayer("#0c0a17", 0.10, 0.30, 18, 46, 0, Hh, 0xF00D);
  skyNear = buildLayer("#12101f", 0.16, 0.42, 34, 78, 0.16, Hh, 0x1E57);
  /* ground + road gradients (screen space) */
  groundGrad = ctx.createLinearGradient(0, H2, 0, H);
  groundGrad.addColorStop(0, T.horizon);
  groundGrad.addColorStop(0.25, "rgb(" + (T.fog[0] * 0.55 | 0) + "," + (T.fog[1] * 0.55 | 0) + "," + (T.fog[2] * 0.6 | 0) + ")");
  groundGrad.addColorStop(1, "#0a0a0e");
  roadGrad = ctx.createLinearGradient(0, H2, 0, H);
  roadGrad.addColorStop(0, T.horizon);
  roadGrad.addColorStop(0.3, "rgb(" + (T.fog[0] * 0.7 + 14 | 0) + "," + (T.fog[1] * 0.7 + 14 | 0) + "," + (T.fog[2] * 0.7 + 18 | 0) + ")");
  roadGrad.addColorStop(1, "#121218");
}

