function spawnPart(x, y, z, vxv, vyv, vzv, life, size, r, g, b, type, add, grav, drag) {
  const p = parts[partHead];
  partHead = (partHead + 1) % PART_N;
  p.x = x; p.y = y; p.z = z; p.vx = vxv; p.vy = vyv; p.vz = vzv;
  p.life = p.life0 = life; p.size = size;
  p.cs = "rgb(" + (r | 0) + "," + (g | 0) + "," + (b | 0) + ")";
  p.type = type; p.add = add; p.grav = grav; p.drag = drag;
