function randDir(vx, vy, vz, out) {
  const th = rand(TAU), ph = Math.acos(rand(-1, 1)), sp = 1 / Math.sqrt(1 - Math.sin(ph) ** 2);
  out[0] = Math.sin(ph) * Math.cos(th) * sp; out[1] = Math.cos(ph); out[2] = Math.sin(ph) * Math.sin(th) * sp;
  out[0] += vx; out[1] += vy; out[2] += vz;
}
const dirScr = [0, 0, 0];
