function updateBolts(dt) {
  for (let i = 0; i < boltPool.length; i++) {
    const b = boltPool[i];
    if (!b.alive) continue;
    b.life -= dt;
    if (b.life <= 0) { b.alive = false; continue; }
    /* soft homing onto nearest drone */
    let bx = 0, by = 0, bz = 0, bd = 4900, found = false;
    for (let j = 0; j < drones.length; j++) {
      const d = drones[j];
      if (d.leave) continue;
      const dx = d.x - b.x, dy = d.y - b.y, dz = d.z - b.z;
      const dd = dx * dx + dy * dy + dz * dz;
      if (dd < bd) { bd = dd; bx = dx; by = dy; bz = dz; found = true; }
    }
    if (found) {
      const L = Math.sqrt(bd) || 1;
      const turn = Math.min(1, 5.5 * dt);
      b.vx += (bx / L - b.vx / 90) * turn * 90;
      b.vy += (by / L - b.vy / 90) * turn * 90;
      b.vz += (bz / L - b.vz / 90) * turn * 90;
    }
    const L2 = Math.sqrt(b.vx * b.vx + b.vy * b.vy + b.vz * b.vz) || 1;
    b.vx = b.vx / L2 * 90; b.vy = b.vy / L2 * 90; b.vz = b.vz / L2 * 90;
    b.x += b.vx * dt; b.y += b.vy * dt; b.z += b.vz * dt;
    for (let j = drones.length - 1; j >= 0; j--) {
      const d = drones[j];
      if (d.leave) continue;
      const dx = b.x - d.x, dy = b.y - d.y, dz = b.z - d.z;
      if (dx * dx + dy * dy + dz * dz < 3.4) {
        b.alive = false;
        d.hp--; d.flash = 0.12;
        SFX.hitDrone();
        sparkBurst(b.x, b.y, b.z, 6, 150, 230, 255);
