function update(dt) {
  tWorld += dt;
  if (state === "menu") { updateDemo(dt); return; }
  if (state === "over") {
    updateParticles(dt); updateRings(dt); updatePopups(dt);
    shakeAmp = Math.max(0, shakeAmp - dt * 2.2);
    flashT = Math.max(0, flashT - dt * 2);
    return;
  }
  if (state !== "playing") return;
  tRun += dt;
  const diff = clamp(tRun / 180, 0, 1);

  /* ---- player: boost / speed ---- */
  const wantBoost = Input.boost && cell > 0.5;
  if (wantBoost) { cell = Math.max(0, cell - 30 * dt); boostK = Math.min(1, boostK + dt * 3.2); }
  else { cell = Math.min(100, cell + 16 * dt); boostK = Math.max(0, boostK - dt * 2.6); }
  if (boostK > 0.05 && prevBoostK <= 0.05) SFX.boost();
  prevBoostK = boostK;
  let sp = 17 + 26 * diff;
  sp *= 1 + 0.55 * boostK;
  if (Input.down) sp *= 0.5;
  if (slowT > 0) { slowT -= dt; sp *= 0.55; }
  speed = sp;

  /* ---- steering ---- */
  const steer = (Input.right ? 1 : 0) - (Input.left ? 1 : 0);
  vx += steer * 42 * dt;
  vx *= Math.max(0, 1 - 7.5 * dt);
  vx = clamp(vx, -11.5, 11.5);
  px += vx * dt;
  const lim = ROAD_HALF - 1.0;
  if (px > lim) { px = lim; vx *= 0.3; }
  else if (px < -lim) { px = -lim; vx *= 0.3; }

  /* ---- jump / gravity ---- */
  Input.jumpBuf -= dt;
  if (Input.jumpBuf > 0 && onGround) { onGround = false; vy = 8.2; SFX.jump(); }
  if (!onGround) {
    vy -= 21 * dt;
    py += vy * dt;
    if (py <= 0) { py = 0; vy = 0; onGround = true; SFX.land(); dustFX(); }
  }
  bobPhase += dt * (4 + speed * 0.5) * (onGround ? 1 : 0.2);
  camZ += sp * dt;
