  /* ---- weapons: heat / overheat ---- */
  if (Input.fire && !overheat && heat < 1) {
    fireCd -= dt;
    if (fireCd <= 0) {
      fireCd = 0.13;
      heat = Math.min(1, heat + 1 / 26);
      recoil = 1; coolDelay = 0;
      SFX.shot(); muzzleFX(); spawnBolt();
      if (heat >= 1) triggerOverheat();
