  }
  if (overheat) {
    overheatT -= dt;
    heat = Math.max(0.3, heat - 0.5 * dt);
    if (heat <= 0.301 && overheatT <= 0) { overheat = false; heat = 0.3; }
  } else if (!Input.fire) {
    coolDelay += dt;
    heat = Math.max(0, heat - (coolDelay > 0.4 ? 1.15 : 0.5) * dt);
