  comboT -= dt; if (comboT <= 0) combo = 0;
  shakeAmp = Math.max(0, shakeAmp - dt * 2.4);
  flashT = Math.max(0, flashT - dt * 2.4);

  /* ---- heartbeat at low integrity ---- */
  if (hp < 30) {
    hbT -= dt;
    if (hbT <= 0) { hbT = lerp(0.5, 1.1, hp / 30); SFX.heartbeat(); }
    if (!lowHpFlag) { lowHpFlag = true; announce("INTEGRITY CRITICAL", "seek a repair cell"); }
  }

  /* ---- score (distance) ---- */
  score += sp * dt * 0.5;

  /* ---- sectors & theme ---- */
  const sec = Math.floor(dist / 500);
  if (sec > lastSector) {
    lastSector = sec;
    themeIdx = (sec + 7) % THEMES.length;
    buildSky();
    announce("SECTOR 0" + (sec + 8), theme().name);
    SFX.sector();
  }

  /* ---- spawners ---- */
  const maxDrones = 3 + (tRun > 60 ? 1 : 0) + (tRun > 120 ? 1 : 0) + (tRun > 200 ? 1 : 0);
  droneT -= dt;
  if (droneT <= 0 && drones.length < maxDrones) {
    spawnDrone(diff);
