  }
  obsT -= dt;
  if (obsT <= 0) { spawnObstacle(); obsT = lerp(2.8, 1.05, diff) * rand(0.75, 1.25); }

  ensureWorld();
  updateDrones(dt, diff);
  updateBolts(dt);
  updateEBolts(dt);
  updateObstacles(dt);
  updatePickups(dt);
  updateParticles(dt);
  updateRings(dt);
  updatePopups(dt);
  hudTick(dt);
}

